CREATE FUNCTION pg_temp.ensure(ok boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT COALESCE(ok,false) THEN RAISE EXCEPTION 'Step 7 assertion failed'; END IF; END $$;
CREATE FUNCTION pg_temp.reject(query text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE query; EXCEPTION WHEN check_violation OR foreign_key_violation THEN RETURN; END; RAISE EXCEPTION 'Expected integrity rejection: %',query; END $$;
INSERT INTO "Tenant" (id,name,slug,"updatedAt") VALUES ('__step7_a','Prova A','__step7_a',now()),('__step7_b','Prova B','__step7_b',now());
