SELECT pg_temp.reject('INSERT INTO "Service" (id,"tenantId","sectorId",name,"durationMinutes","basePrice") VALUES (''__step7_invalid_service'',''__step7_b'',''__step7_a_second_sector'',''No'',30,1)');
