INSERT INTO "Appointment" (id,"tenantId","customerId","serviceId","collaboratorId","startsAt","endsAt",status,"updatedAt") VALUES ('__step7_appointment_a','__step7_a','__step7_customer','__step7_service_a','__step7_prof','2030-11-11T10:00:00Z','2030-11-11T10:30:00Z','confirmed',now());
