SELECT pg_temp.reject('INSERT INTO "Appointment" (id,"tenantId","customerId","serviceId","collaboratorId","startsAt","endsAt",status,"updatedAt") VALUES (''__step7_overlap'',''__step7_a'',''__step7_customer'',''__step7_service_second'',''__step7_prof'',''2030-11-11T10:00:00Z'',''2030-11-11T10:30:00Z'',''confirmed'',now())');
SELECT pg_temp.reject('INSERT INTO "Appointment" (id,"tenantId","customerId","serviceId","roomId","startsAt","endsAt",status,"updatedAt") VALUES (''__step7_wrong_room'',''__step7_a'',''__step7_customer'',''__step7_service_a'',''__step7_room'',''2030-11-11T14:00:00Z'',''2030-11-11T14:30:00Z'',''confirmed'',now())');
SELECT pg_temp.reject('INSERT INTO "Appointment" (id,"tenantId","customerId","serviceId","startsAt","endsAt",status,"updatedAt") VALUES (''__step7_wrong_customer'',''__step7_a'',''__step7_foreign_customer'',''__step7_service_a'',''2030-11-11T14:00:00Z'',''2030-11-11T14:30:00Z'',''confirmed'',now())');
